LEVEL = 1
CFG = {1: {"used": 4, "limit": 5}, 2: {"used": 9, "limit": 5}, 3: {"used": 30, "limit": 5}}
used, limit = CFG[LEVEL]["used"], CFG[LEVEL]["limit"]
if used <= limit: print("step finished in %ds (limit %ds): ok" % (used, limit))
elif used <= limit * 2: print("slow step %ds: retry with 2x budget" % used)
else: print("STUCK step %ds: watchdog ABORT, partial progress logged" % used)

