LEVEL = 1
CFG = {1: 2, 2: 3, 3: 4}
N = CFG[LEVEL]
done, log = [], []
try:
    for i in range(N):
        done.append(i); log.append("do-%d" % i)
        if i == N - 2: raise RuntimeError("step failed")
except RuntimeError:
    for i in reversed(done):
        log.append("undo-%d" % i)
print("saga log:", log)

